blocks.code:
:root {
 --bg: #0a0f1e;
 --surface: #121a2b;
 --surface-light: #182338;
 --border: #273449;
 --text: #f8fafc;
 --muted: #94a3b8;
 --primary: #38bdf8;
 --accent: #a855f7;
 --radius: 18px;
 --container: 1120px;
}

* {
 box-sizing: border-box;
}

html {
 scroll-behavior: smooth;
}

body {
 margin: 0;
 background: var(--bg);
 color: var(--text);
 font-family: Arial, sans-serif;
 line-height: 1.6;
}

img {
 max-width: 100%;
 height: auto;
}

a {
 color: inherit;
}

.container {
 width: min(92%, var(--container));
 margin-inline: auto;
}

.site-header {
 position: sticky;
 top: 0;
 z-index: 100;
 background: rgba(10, 15, 30, 0.92);
 border-bottom: 1px solid var(--border);
}

.nav-container {
 min-height: 72px;
 display: flex;
 align-items: center;
 justify-content: space-between;
 gap: 24px;
}

.logo {
 font-size: 1.2rem;
 font-weight: 800;
 text-decoration: none;
}

.nav-links {
 display: flex;
 gap: 24px;
}

.nav-links a {
 color: var(--muted);
 text-decoration: none;
 transition: color 0.2s ease;
}

.nav-links a:hover,
.nav-links a:focus-visible {
 color: var(--text);
}

.nav-button,
.primary-button,
.secondary-button {
 display: inline-flex;
 align-items: center;
 justify-content: center;
 padding: 11px 17px;
 border-radius: 10px;
 text-decoration: none;
 font-weight: 700;
}

.nav-button,
.primary-button {
 background: var(--primary);
 color: #07111f;
}

.secondary-button {
 border: 1px solid var(--border);
 color: var(--text);
}

.hero {
 padding: clamp(60px, 10vw, 120px) 0;
}

.hero-content {
 display: grid;
 grid-template-columns: minmax(0, 1.4fr) minmax(280px, 0.6fr);
 gap: 60px;
 align-items: center;
}

.eyebrow {
 margin: 0 0 12px;
 color: var(--primary);
 font-size: 0.78rem;
 font-weight: 800;
 letter-spacing: 0.12em;
}

.hero h1 {
 max-width: 760px;
 margin: 0;
 font-size: clamp(2.4rem, 7vw, 5rem);
 line-height: 1.02;
}

.hero-description {
 max-width: 650px;
 margin: 24px 0;
 color: var(--muted);
 font-size: 1.08rem;
}

.hero-actions {
 display: flex;
 flex-wrap: wrap;
 gap: 12px;
}

.hero-card {
 padding: 28px;
 border: 1px solid var(--border);
 border-radius: var(--radius);
 background: var(--surface);
 box-shadow: 0 20px 60px rgba(0,0,0,0.25);
}

.card-label {
 color: var(--primary);
 font-size: 0.75rem;
 font-weight: 800;
}

.hero-card h2 {
 margin: 12px 0 8px;
}

.hero-card p {
 color: var(--muted);
}

.progress-track {
 height: 8px;
 margin-top: 24px;
 overflow: hidden;
 border-radius: 999px;
 background: var(--border);
}

.progress-bar {
 width: 90%;
 height: 100%;
 border-radius: inherit;
 background: linear-gradient(90deg, var(--primary), var(--accent));
}

.progress-text {
 display: block;
 margin-top: 10px;
 color: var(--muted);
 font-size: 0.85rem;
}

.section {
 padding: 90px 0;
}

.section-heading {
 max-width: 650px;
 margin-bottom: 40px;
}

.section-heading h2 {
 margin: 0 0 10px;
 font-size: clamp(2rem, 5vw, 3.2rem);
}

.section-heading p:last-child {
 margin: 0;
 color: var(--muted);
}

.course-grid {
 display: grid;
 grid-template-columns: repeat(3, minmax(0, 1fr));
 gap: 20px;
}

.course-card {
 position: relative;
 padding: 28px;
 border: 1px solid var(--border);
 border-radius: var(--radius);
 background: var(--surface);
 transition: transform 0.25s ease, border-color 0.25s ease, box-shadow 0.25s ease;
}

.course-card:hover {
 transform: translateY(-6px);
 border-color: var(--primary);
 box-shadow: 0 18px 40px rgba(0,0,0,0.25);
}

.featured-card {
 background: linear-gradient(145deg, var(--surface), var(--surface-light));
}

.course-number {
 color: var(--primary);
 font-weight: 800;
}

.course-card h3 {
 margin: 20px 0 8px;
 font-size: 1.5rem;
}

.course-card p {
 color: var(--muted);
}

.card-link {
 display: inline-block;
 margin-top: 16px;
 color: var(--primary);
 text-decoration: none;
 font-weight: 700;
}

.stats-section {
 padding: 50px 0;
 border-top: 1px solid var(--border);
 border-bottom: 1px solid var(--border);
 background: var(--surface);
}

.stats-grid {
 display: grid;
 grid-template-columns: repeat(4, 1fr);
 gap: 20px;
 text-align: center;
}

.stat strong {
 display: block;
 font-size: clamp(2rem, 5vw, 3rem);
}

.stat span {
 color: var(--muted);
}

.cta-section {
 padding: 90px 0;
}

.cta-content {
 display: flex;
 align-items: center;
 justify-content: space-between;
 gap: 30px;
 padding: 40px;
 border: 1px solid var(--border);
 border-radius: var(--radius);
 background: var(--surface);
}

.cta-content h2 {
 margin: 0 0 8px;
 font-size: clamp(1.8rem, 4vw, 3rem);
}

.cta-content p:last-child {
 margin: 0;
 color: var(--muted);
}

.footer {
 border-top: 1px solid var(--border);
 padding: 24px 0;
 color: var(--muted);
 font-size: 0.9rem;
}

.footer-content {
 display: flex;
 align-items: center;
 justify-content: space-between;
 gap: 20px;
}

@media (max-width: 850px) {
 .hero-content {
 grid-template-columns: 1fr;
 gap: 35px;
 }

 .course-grid {
 grid-template-columns: repeat(2, minmax(0, 1fr));
 }

 .stats-grid {
 grid-template-columns: repeat(2, 1fr);
 }
}

@media (max-width: 620px) {
 .nav-container {
 flex-wrap: wrap;
 padding: 14px 0;
 }

 .nav-links {
 order: 3;
 width: 100%;
 justify-content: center;
 gap: 14px;
 }

 .nav-button {
 padding: 9px 13px;
 }

 .hero {
 padding: 65px 0;
 }

 .course-grid,
 .stats-grid {
 grid-template-columns: 1fr;
 }

 .cta-content,
 .footer-content {
 flex-direction: column;
 align-items: flex-start;
 }
}

@media (prefers-reduced-motion: reduce) {
 *,
 *::before,
 *::after {
 animation-duration: 0.01ms !important;
 animation-iteration-count: 1 !important;
 transition-duration: 0.01ms !important;
 scroll-behavior: auto !important;
 }
}

@keyframes fadeUp {
 from {
 opacity: 0;
 transform: translateY(18px);
 }

 to {
 opacity: 1;
 transform: translateY(0);
 }
}

.hero-text {
 animation: fadeUp 0.6s ease-out both;
}

.hero-card {
 animation: fadeUp 0.6s ease-out 0.1s both;
}

.primary-button,
.secondary-button {
 transition: transform 0.2s ease, box-shadow 0.2s ease, background 0.2s ease;
}

.primary-button:hover,
.secondary-button:hover {
 transform: translateY(-2px);
 box-shadow: 0 8px 20px rgba(0,0,0,0.2);
}
